fn removeElement(nums: &mut Vec<i32>, val: i32) -> usize {
    // `write` is the index in `nums` where we write the next non-`val` element.
    let mut write = 0;
    for &x in nums.iter() {
        if x != val {
            nums[write] = x;
            write += 1;
        }
    }
    write
}

